#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# GCM VALIDATION DATA loader
#~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
# Pre-computed validation of every GCM method against the bundled experimental
# test sets (Joback, Biswas, Alshehri, Hansen, Zhao, Chrastil). Generated by
# data-raw/gcm_validation/run_validation.R and stored compressed in inst/extdata
# (loaded on demand, NOT in sysdata). Used by the Solute Characterization
# parity-plot viewer.

#' @title Load the bundled GCM validation dataset
#' @description Reads the pre-computed validation results: predicted vs experimental values for
#'   every GCM method against each applicable experimental test set, the per-compound group
#'   assignments, and per-(test set x property x method) summary statistics (AARD, RMSE, R2, bias).
#' @return A \code{list} with elements \code{predictions} (long data.frame, all experimental test sets
#'   merged by property: property, method, name, smiles, source, experimental, predicted, n_groups,
#'   status, coverage_gap, abs_pct_err, category), \code{summary} (per property x method: accuracy over
#'   in-domain "Valid" points plus per-category counts), \code{references} (property x source counts),
#'   and \code{meta}. The \code{category} is one of Valid / High error / Missing atoms / Out of domain /
#'   Voided / Failed; only "Valid" feeds the best-fit. Returns \code{NULL} (with a warning) if the
#'   dataset has not been generated. Built by \code{data-raw/gcm_validation/build_app_merged.R}.
#' @seealso \code{\link{est_gcm}}, \code{\link{compare_gcm}}
#' @export
gcm_validation <- function() {
  f <- system.file("extdata", "properties", "gcm_validation.rds", package = "supeRcrit")
  if (!nzchar(f)) f <- file.path("inst", "extdata", "properties", "gcm_validation.rds")   # dev fallback (load_all)
  if (!file.exists(f)) {
    warning("GCM validation dataset not found. Generate it with data-raw/gcm_validation/run_validation.R.",
            call. = FALSE)
    return(NULL)
  }
  readRDS(f)
}
